INSERT INTO `about_content` VALUES (1,'{\"en\": \"Drilling engineer, researcher, and educator working at the intersection of engineering and artificial intelligence.\", \"es\": \"Ingeniero, investigador y educador, apasionado por la perforación, los datos y la enseñanza.\"}','{\"en\": \"<p>Howdy! I am Abraham, a drilling engineer, researcher, and educator working at the intersection of engineering and artificial intelligence.</p>\\r\\n\\r\\n<p>My work focuses on applying advanced modeling and artificial intelligence to solve practical challenges in drilling engineering. I currently work as a Drilling and Completion Engineer at Ecopetrol in Colombia, where I am part of the Analytics and Control Team and serve as the technical lead for drilling optimization through stuck pipe prevention.</p>\\r\\n\\r\\n<p>I am passionate about turning engineering knowledge, data, and emerging technologies into practical tools that improve how we understand, design, and operate wells, while helping others develop the skills to do the same.</p>\", \"es\": \"<p>¡Hola! Soy Abraham, ingeniero de perforación, investigador y docente, y desarrollo mi trabajo en la intersección entre la ingeniería y la inteligencia artificial (IA).<br><br>Mi trabajo se centra en aplicar técnicas avanzadas de modelamiento e IA para resolver desafíos prácticos de la ingeniería de perforación. Actualmente me desempeño como ingeniero de perforación y completamiento en Ecopetrol, Colombia, donde hago parte del equipo de Analítica y Control y lidero técnicamente las iniciativas de optimización de la perforación mediante la prevención de eventos de pega de tubería («stuck pipe»).<br><br>Me apasiona transformar el conocimiento en ingeniería, los datos y tecnologías emergentes en herramientas prácticas que mejoren nuestra manera de comprender, diseñar y operar pozos, así como contribuir al desarrollo de las capacidades de otras personas para lograrlo.</p>\"}','2026-08-13 06:41:10','2026-11-15 23:51:35');
/*!40000 ALTER TABLE `about_content` ENABLE KEYS */;
UNLOCK TABLES;

