INSERT INTO `awards` VALUES (1,'{\"en\": \"1st Place 🥇 SPE Gulf Coast North America/Southwestern North America Regional Paper Contest—Doctoral Division\", \"es\": \"1.er lugar 🥇 Concurso Regional de Artículos de la SPE Gulf Coast North America/Southwestern North America — División Doctoral\"}','Society of Petroleum Engineers','2026-03-28','{\"en\": \"For placing 1st in the PhD Division of the 2026 SPE Gulf Coast NA/Southwestern NA Regional Paper Contest with his presentation: \\\"Hole Cleaning and Borehole Stability Management with Integrated Real-Time Measurements and Modeling\\\"\", \"es\": \"Por obtener el primer lugar en la División de Doctorado del Concurso Regional de Artículos 2026 de la SPE Gulf Coast NA/Southwestern NA con su presentación: \\\"Hole Cleaning and Borehole Stability Management with Integrated Real-Time Measurements and Modeling\\\"\"}','uploads/awards/9eed6fae-56bc-4c3b-862f-07b3b4ccbc88.jpg',0,1,'2026-08-15 21:11:58','2026-11-15 22:44:07'),(2,'{\"en\": \"1st Place 🥇 SPE Paper Contest—Doctoral Division\", \"es\": \"1.er lugar 🥇 Concurso de Artículos de la SPE — División Doctoral\"}','The University of Texas at Austin','2026-02-05','{\"en\": \"For placing 1st in the PhD Division of the 2026 SPE Local Paper Contest at The University of Texas at Austin, with his presentation titled \\\"Hole Cleaning and Borehole Stability Management with Integrated Real-Time Measurements and Modeling\\\"\", \"es\": \"Por obtener el primer lugar en la División de Doctorado del Concurso Local de Artículos 2026 de la SPE en The University of Texas at Austin, con su presentación titulada \\\"Hole Cleaning and Borehole Stability Management with Integrated Real-Time Measurements and Modeling\\\"\"}','uploads/awards/05281edb-71ff-4bf1-b6f0-64af16d28821.jpeg',0,1,'2026-11-08 19:09:34','2026-11-15 22:44:07'),(3,'{\"en\": \"Best of the Best Paper Drilling Conference\", \"es\": \"Lo Mejor de lo Mejor — Drilling Conference (Best of the Best Paper)\"}','Society of Petroleum Engineers','2024-09-25','{\"en\": \"In recognition of exceptional quality paper & presentation: \\\"Comparing Drilling Anomaly Prediction by Purely Data-Driven and Hybrid Analysis Methods - Case Study of Utah FORGE Geothermal Wells,\\\" presented at the 2024 IADC/SPE International Drilling Conference and Exhibition\", \"es\": \"En reconocimiento a la calidad excepcional del artículo y la presentación: \\\"Comparing Drilling Anomaly Prediction by Purely Data-Driven and Hybrid Analysis Methods - Case Study of Utah FORGE Geothermal Wells\\\", presentado en la IADC/SPE International Drilling Conference and Exhibition 2024\"}','uploads/awards/87dbacc9-be44-49b6-ac4b-dbfae6776f1f.jpg',0,1,'2026-11-08 19:12:04','2026-11-15 22:44:07'),(4,'{\"en\": \"1st Place 🥇 Energy AI Hackathon 2023\", \"es\": \"1.er lugar 🥇 Energy AI Hackathon 2023\"}','The University of Texas at Austin','2023-01-22','{\"en\": \"Energy A.I. 2023 Hackathon at The University of Texas at Austin\", \"es\": \"Energy A.I. Hackathon 2023 en The University of Texas at Austin\"}','uploads/awards/0e01c242-c904-4da4-9664-6262d1615afd.png',0,1,'2026-11-09 00:04:52','2026-11-15 22:44:07'),(5,'{\"en\": \"Cum Laude Degree 🎖️\", \"es\": \"Grado con Honores Cum Laude 🎖️\"}','Pontificia Universidad Javeriana','2022-03-25','{\"en\": \"Pontificia Universidad Javeriana awards the Cum Laude honors distinction in recognition of your outstanding academic performance throughout the Master\'s Degree in Systems and Computational Engineering program\", \"es\": \"La Pontificia Universidad Javeriana concede el grado con honores CUM LAUDE por su desempeño académico durante sus estudios en el programa Maestría en Ingeniería de Sistemas y Computación\"}','uploads/awards/5bbf3802-06c9-44aa-a023-5d2d32fcbb69.png',0,1,'2026-11-09 00:14:17','2026-11-09 00:14:17'),(6,'{\"en\": \"Fulbright Scholarship\", \"es\": \"Beca Fulbright\"}','Fulbright & Ministerio de Ciencias y Tecnología','2022-05-15','[]','uploads/awards/dabcd3ba-cc36-47ec-996f-1085c0581e67.png',0,1,'2026-11-09 00:18:12','2026-11-09 00:18:12');
