INSERT INTO `public_phrases` VALUES (1,'empty_state.blog.title','Empty States','{\"en\": \"No articles yet\", \"es\": \"Aún no hay artículos\"}','2026-08-13 06:15:20','2026-11-15 22:44:07'),(2,'empty_state.blog.message','Empty States','{\"en\": \"New writing will appear here soon — check back later.\", \"es\": \"Pronto aparecerán nuevas publicaciones aquí; vuelve más tarde.\"}','2026-08-13 06:15:20','2026-11-15 22:44:07'),(3,'empty_state.research.title','Empty States','{\"en\": \"No research projects yet\", \"es\": \"Aún no hay proyectos de investigación\"}','2026-08-13 06:15:20','2026-11-15 22:44:07'),(4,'empty_state.research.message','Empty States','{\"en\": \"Project write-ups will appear here soon.\", \"es\": \"Pronto aparecerán aquí las descripciones de los proyectos.\"}','2026-08-13 06:15:20','2026-11-15 22:44:07'),(5,'empty_state.publications.title','Empty States','{\"en\": \"No publications yet\", \"es\": \"Aún no hay publicaciones\"}','2026-08-13 06:15:20','2026-11-15 22:44:07'),(6,'empty_state.publications.message','Empty States','{\"en\": \"Papers and conference proceedings will appear here soon.\", \"es\": \"Pronto aparecerán aquí artículos de revista y memorias de congresos.\"}','2026-08-13 06:15:20','2026-11-15 22:44:07'),(7,'empty_state.news.title','Empty States','{\"en\": \"No news yet\", \"es\": \"Aún no hay noticias\"}','2026-08-13 06:15:20','2026-11-15 22:44:07'),(8,'empty_state.news.message','Empty States','{\"en\": \"Announcements and updates will appear here soon.\", \"es\": \"Pronto aparecerán aquí anuncios y novedades.\"}','2026-08-13 06:15:20','2026-11-15 22:44:07'),(9,'empty_state.quotes.title','Empty States','{\"en\": \"No quotes yet\", \"es\": \"Aún no hay citas\"}','2026-08-13 06:15:20','2026-11-15 22:44:07'),(10,'empty_state.quotes.message','Empty States','{\"en\": \"Quotes worth sharing will appear here soon.\", \"es\": \"Pronto aparecerán aquí citas que vale la pena compartir.\"}','2026-08-13 06:15:20','2026-11-15 22:44:07'),(11,'empty_state.about.title','Empty States','{\"en\": \"About Me is coming soon\", \"es\": \"La sección Sobre mí estará disponible pronto\"}','2026-08-15 08:23:12','2026-11-15 22:44:07'),(12,'empty_state.about.message','Empty States','{\"en\": \"A full profile will appear here soon.\", \"es\": \"Pronto aparecerá aquí un perfil completo.\"}','2026-08-15 08:23:12','2026-11-15 22:44:07'),(13,'quotes.title','Section Headings','{\"en\": \"Quotes I Like\", \"es\": \"Citas que me gustan\"}','2026-08-15 08:23:12','2026-11-15 22:44:07'),(14,'contact.intro','Contact','{\"en\": \"Have a question, a collaboration in mind, or just want to say hello? Send a message and I will get back to you.\", \"es\": \"¿Tienes una pregunta, una idea de colaboración o simplemente quieres saludar? Envíame un mensaje y te responderé.\"}','2026-08-15 08:23:12','2026-11-15 22:44:07'),(15,'empty_state.awards.title','Empty States','{\"en\": \"No awards yet\", \"es\": \"Aún no hay premios\"}','2026-08-15 20:44:35','2026-11-15 22:44:07'),(16,'empty_state.awards.message','Empty States','{\"en\": \"Awards and distinctions will appear here soon.\", \"es\": \"Pronto aparecerán aquí premios y distinciones.\"}','2026-08-15 20:44:35','2026-11-15 22:44:07'),(17,'hero.greeting','Hero','{\"en\": \"Hello, I\'m\", \"es\": \"Hola, soy\"}','2026-11-15 22:47:43','2026-11-15 22:47:43'),(18,'hero.roles','Hero','{\"en\": \"Drilling Engineer|AI/ML Researcher|Ph.D. in Petroleum Engineering|Educator\", \"es\": \"Ingeniero de Perforación|Investigador en IA/ML|Ph.D. en Ingeniería de Petróleos|Educador\"}','2026-11-15 22:47:43','2026-11-15 22:47:43'),(19,'footer.cta_title','Footer','{\"en\": \"Let\'s build the future of drilling together.\", \"es\": \"Construyamos juntos el futuro de la perforación.\"}','2026-11-15 22:47:43','2026-11-15 22:47:43'),(20,'footer.cta_text','Footer','{\"en\": \"Open to research collaborations, industry projects and speaking invitations.\", \"es\": \"Abierto a colaboraciones de investigación, proyectos con la industria e invitaciones como conferencista.\"}','2026-11-15 22:47:43','2026-11-15 22:47:43'),(21,'section_lead.about','Section Headings','{\"en\": \"Engineer, researcher and educator bridging physics and artificial intelligence.\", \"es\": \"Ingeniero, investigador y educador que une la física y la inteligencia artificial.\"}','2026-11-15 22:47:43','2026-11-15 22:47:43'),(22,'section_lead.news','Section Headings','{\"en\": \"Conferences, awards and milestones from the field and the lab.\", \"es\": \"Conferencias, premios y logros desde el campo y el laboratorio.\"}','2026-11-15 22:47:43','2026-11-15 22:47:43'),(23,'section_lead.research','Section Headings','{\"en\": \"Hybrid physics + AI models for safer, smarter well construction.\", \"es\": \"Modelos híbridos física + IA para una construcción de pozos más segura e inteligente.\"}','2026-11-15 22:47:43','2026-11-15 22:47:43'),(24,'section_lead.publications','Section Headings','{\"en\": \"Peer-reviewed journal articles and conference papers.\", \"es\": \"Artículos en revistas arbitradas y ponencias en congresos.\"}','2026-11-15 22:47:43','2026-11-15 22:47:43'),(25,'section_lead.awards','Section Headings','{\"en\": \"Recognition for research, presentations and academic work.\", \"es\": \"Reconocimientos a la investigación, las presentaciones y el trabajo académico.\"}','2026-11-15 22:47:43','2026-11-15 22:47:43'),(26,'section_lead.blog','Section Headings','{\"en\": \"Notes on drilling, data science and engineering.\", \"es\": \"Notas sobre perforación, ciencia de datos e ingeniería.\"}','2026-11-15 22:47:43','2026-11-15 22:47:43'),(27,'section_lead.contact','Section Headings','{\"en\": \"Let\'s talk about your next project.\", \"es\": \"Hablemos de tu próximo proyecto.\"}','2026-11-15 22:47:43','2026-11-15 22:47:43');
