INSERT INTO `quotes` VALUES (1,'Eric Hoffer','{\"en\": \"In times of change, learners inherit the earth, while the learned find themselves beautifully equipped to deal with a world that no longer exists.\", \"es\": \"En tiempos de cambio, los que aprenden heredan la tierra, mientras que los que ya han aprendido se encuentran maravillosamente equipados para enfrentarse a un mundo que ya no existe.\"}','uploads/quotes/31d860dd-82cf-44fe-8b74-7b1ffc3fc582.jpg',0,1,'2026-08-12 23:23:09','2026-08-15 05:30:11'),(2,'José R. Capablanca','{\"en\": \"You may learn much more from a game you lose than from a game you win.\", \"es\": \"Puedes aprender más de un juego que pierdes que de un juego que ganas.\"}','uploads/quotes/15431627-eab4-4bda-9593-196b73511a05.jpg',0,1,'2026-08-13 05:46:32','2026-08-15 05:33:53'),(3,'Michael Pyrcz','{\"en\": \"Energy has been big data long before tech learned about big data.\", \"es\": \"La industria energía ha sido \\\"Big Data\\\" mucho antes que los grupos tecnológicos aprendieran de Big Data.\"}','uploads/quotes/40101bf9-b5eb-4509-80a9-0953972dd650.webp',0,1,'2026-08-13 05:50:04','2026-08-13 05:50:04'),(4,'Carl F. Gauß','{\"en\": \"It is not knowledge, but the act of learning, not the possession of but the act of getting there, which grants the greatest enjoyment.\", \"es\": \"No es el conocimiento, sino el acto de aprender; no es la posesión, sino el acto de llegar a ello, lo que brinda el mayor placer.\"}','uploads/quotes/7ef863ee-adac-4045-8755-dd69d0ffd96a.jpg',0,1,'2026-08-13 05:53:13','2026-08-15 05:34:26');
